    #[test]
    fn content_pack_payloads_reject_invalid_buena_password_categories_at_load_time() {
        let cases = vec![
            (
                "malformed category id",
                serde_json::json!({
                    "order": ["Healing Items"],
                    "categories": {
                      "Healing Items": {
                        "categoryType": "BUENA_ITEM",
                        "points": 12,
                        "options": ["POTION"]
                      }
                    }
                }),
                "Buena password category id 'Healing Items' must be exact ASCII alphanumeric or underscore",
            ),
            (
                "extra category not in order",
                serde_json::json!({
                    "order": ["HealingItems"],
                    "categories": {
                      "HealingItems": {
                        "categoryType": "BUENA_ITEM",
                        "points": 12,
                        "options": ["POTION"]
                      },
                      "ExtraItems": {
                        "categoryType": "BUENA_ITEM",
                        "points": 12,
                        "options": ["ANTIDOTE"]
                      }
                    }
                }),
                "Buena password category 'ExtraItems' is missing from order",
            ),
            (
                "unknown category type",
                serde_json::json!({
                    "order": ["HealingItems"],
                    "categories": {
                      "HealingItems": {
                        "categoryType": "BUENA_BERRY",
                        "points": 12,
                        "options": ["POTION"]
                      }
                    }
                }),
                "Buena password category 'HealingItems' has unknown type 'BUENA_BERRY'",
            ),
            (
                "zero points",
                serde_json::json!({
                    "order": ["HealingItems"],
                    "categories": {
                      "HealingItems": {
                        "categoryType": "BUENA_ITEM",
                        "points": 0,
                        "options": ["POTION"]
                      }
                    }
                }),
                "Buena password category 'HealingItems' points must be nonzero",
            ),
            (
                "malformed option",
                serde_json::json!({
                    "order": ["HealingItems"],
                    "categories": {
                      "HealingItems": {
                        "categoryType": "BUENA_ITEM",
                        "points": 12,
                        "options": ["SUPER POTION"]
                      }
                    }
                }),
                "Buena password category 'HealingItems' option 0 'SUPER POTION' must be exact ASCII alphanumeric or underscore",
            ),
            (
                "reserved legacy category id",
                serde_json::json!({
                    "order": ["legacyCategory"],
                    "categories": {
                      "legacyCategory": {
                        "categoryType": "BUENA_ITEM",
                        "points": 12,
                        "options": ["POTION"]
                      }
                    }
                }),
                "Buena password category id 'legacyCategory' uses reserved modpack payload prefix",
            ),
        ];

        for (label, payload, expected) in cases {
            let error = GameDataSet::default()
                .apply_content_pack_payload(ContentPackCategory::BuenaPasswordCategories, payload)
                .expect_err(label);

            assert!(
                format!("{error:#}").contains(expected),
                "{label} produced unexpected error: {error:#}"
            );
        }
    }

