    #[test]
    fn content_pack_payloads_reject_invalid_happiness_data_table() {
        for (payload, expected) in [
            (
                serde_json::json!({
                    "changes": {},
                    "services": {
                        "DaisysGrooming": [
                            { "rollWeight": 255, "scriptValue": 2, "changeCode": 18 }
                        ]
                    }
                }),
                "requires at least one explicit change row",
            ),
            (
                serde_json::json!({
                    "changes": {
                        "18": { "code": "HAPPINESS GROOMING", "low": 3, "mid": 3, "high": 1 }
                    },
                    "services": {
                        "DaisysGrooming": [
                            { "rollWeight": 255, "scriptValue": 2, "changeCode": 18 }
                        ]
                    }
                }),
                "happiness data change code label for 18",
            ),
            (
                serde_json::json!({
                    "changes": {
                        "18": { "code": "HAPPINESS_GROOMING", "low": 3, "mid": 3, "high": 1 },
                        "19": { "code": "HAPPINESS_GROOMING", "low": 5, "mid": 5, "high": 2 }
                    },
                    "services": {
                        "DaisysGrooming": [
                            { "rollWeight": 255, "scriptValue": 2, "changeCode": 18 }
                        ]
                    }
                }),
                "duplicate happiness change code",
            ),
            (
                serde_json::json!({
                    "changes": {
                        "18": { "code": "HAPPINESS_GROOMING", "low": 3, "mid": 3, "high": 1 }
                    },
                    "services": {}
                }),
                "requires explicit service probability tables",
            ),
            (
                serde_json::json!({
                    "changes": {
                        "18": { "code": "HAPPINESS_GROOMING", "low": 3, "mid": 3, "high": 1 }
                    },
                    "services": {
                        "Daisys Grooming": [
                            { "rollWeight": 255, "scriptValue": 2, "changeCode": 18 }
                        ]
                    }
                }),
                "happiness data service routine id",
            ),
            (
                serde_json::json!({
                    "changes": {
                        "18": { "code": "HAPPINESS_GROOMING", "low": 3, "mid": 3, "high": 1 }
                    },
                    "services": {
                        "DaisysGrooming": []
                    }
                }),
                "requires at least one outcome",
            ),
            (
                serde_json::json!({
                    "changes": {
                        "18": { "code": "HAPPINESS_GROOMING", "low": 3, "mid": 3, "high": 1 }
                    },
                    "services": {
                        "DaisysGrooming": [
                            { "rollWeight": 255, "scriptValue": 2, "changeCode": 19 }
                        ]
                    }
                }),
                "references missing change code 19",
            ),
        ] {
            let error = GameDataSet::default()
                .apply_content_pack_payload(ContentPackCategory::HappinessData, payload)
                .expect_err("invalid happiness data table must be rejected");

            assert!(format!("{error:#}").contains(expected), "{error:#}");
        }
    }

